package com.crowdin.client.core.http.impl.json;

import com.crowdin.client.core.http.exceptions.HttpBadRequestException;
import com.crowdin.client.core.http.exceptions.HttpException;
import com.crowdin.client.projectsgroups.model.Project;
import com.crowdin.client.sourcefiles.model.FileInfo;
import com.crowdin.client.stringtranslations.model.LanguageTranslations;
import com.fasterxml.jackson.databind.JsonMappingException;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class JacksonJsonTransformerTest {

    @Test
    public void parseHttpExceptionTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{\"error\":{\"code\":400,\"message\":\"Bad Request\"}}";
        HttpException exception = transformer.parse(json, HttpException.class);
        assertEquals(400, exception.getError().getCode());
        assertEquals("Bad Request", exception.getError().getMessage());
    }

    @Test
    public void parseHttpBadRequestExceptionTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{\"error\":{\"code\":400,\"message\":\"Bad Request\"}}";
        HttpBadRequestException exception = transformer.parse(json, HttpBadRequestException.class);
        assertEquals(400, exception.getError().getCode());
        assertEquals("Bad Request", exception.getError().getMessage());
    }

    @Test(expected = JsonMappingException.class)
    public void parseInvalidJsonTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{\"invalid\":\"json\"}";
        transformer.parse(json, HttpException.class);
    }

    @Test
    public void convertProjectTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        Project project = new Project();
        project.setId(1L);
        project.setName("TestProject");
        String json = transformer.convert(project);
        assertTrue(json.contains("1"));
        assertTrue(json.contains("TestProject"));
    }

    @Test
    public void convertFileInfoTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        FileInfo fileInfo = new FileInfo();
        fileInfo.setId(1L);
        fileInfo.setName("TestFile");
        String json = transformer.convert(fileInfo);
        assertTrue(json.contains("1"));
        assertTrue(json.contains("TestFile"));
    }

    @Test
    public void convertLanguageTranslationsTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        LanguageTranslations languageTranslations = new LanguageTranslations();
        languageTranslations.setLanguageId("1");
        String json = transformer.convert(languageTranslations);
        assertTrue(json.contains("1"));
    }

}
